package com.klikli_dev.occultism.client.model.entity;

import com.klikli_dev.occultism.client.render.entity.state.GreedyFamiliarRenderState;
import net.minecraft.client.model.EntityModel;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.CubeListBuilder;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.client.model.geom.builders.MeshDefinition;
import net.minecraft.client.model.geom.builders.PartDefinition;
import net.minecraft.util.Mth;

public class GreedyFamiliarModel extends EntityModel<GreedyFamiliarRenderState> {
    private static final float PI = (float) Math.PI;
    public ModelPart body, rightArm, chest1, leftArm, rightLeg, leftLeg, head, chest2, monster, monsterLeftEye, monsterRightEye, monsterLeftEar, monsterRightEar, leftEar, rightEar, nose;
    public GreedyFamiliarModel(ModelPart part) { super(part); body=part.getChild("body"); rightArm=body.getChild("rightArm"); chest1=body.getChild("chest1"); leftArm=body.getChild("leftArm"); rightLeg=body.getChild("rightLeg"); leftLeg=body.getChild("leftLeg"); head=body.getChild("head"); chest2=chest1.getChild("chest2"); monster=chest1.getChild("monster"); monsterLeftEye=monster.getChild("monsterLeftEye"); monsterRightEye=monster.getChild("monsterRightEye"); monsterLeftEar=monster.getChild("monsterLeftEar"); monsterRightEar=monster.getChild("monsterRightEar"); leftEar=head.getChild("leftEar"); rightEar=head.getChild("rightEar"); nose=head.getChild("nose"); }
    public static LayerDefinition createBodyLayer(){MeshDefinition mesh=new MeshDefinition();PartDefinition parts=mesh.getRoot();PartDefinition body=parts.addOrReplaceChild("body", CubeListBuilder.create().texOffs(0,10).addBox(-2.5F,-5.0F,-1.5F,5.0F,5.0F,3.0F,false), PartPose.offsetAndRotation(0.0F,19.0F,0.6F,0,0,0));PartDefinition rightArm=body.addOrReplaceChild("rightArm", CubeListBuilder.create().texOffs(16,21).addBox(-2.0F,0.0F,-1.0F,2.0F,6.0F,2.0F,true), PartPose.offsetAndRotation(-2.5F,-5.0F,0.0F,0,0,0));PartDefinition chest1=body.addOrReplaceChild("chest1", CubeListBuilder.create().texOffs(12,14).addBox(-2.0F,-3.0F,0.0F,4.0F,3.0F,4.0F,false), PartPose.offsetAndRotation(0.0F,0.5F,1.5F,0,0,0));PartDefinition leftArm=body.addOrReplaceChild("leftArm", CubeListBuilder.create().texOffs(16,21).addBox(0.0F,0.0F,-1.0F,2.0F,6.0F,2.0F,false), PartPose.offsetAndRotation(2.5F,-5.0F,0.0F,0,0,0));PartDefinition rightLeg=body.addOrReplaceChild("rightLeg", CubeListBuilder.create().texOffs(8,24).addBox(-1.0F,0.0F,-1.0F,2.0F,5.0F,2.0F,true), PartPose.offsetAndRotation(-1.5F,0.0F,0.0F,0,0,0));PartDefinition leftLeg=body.addOrReplaceChild("leftLeg", CubeListBuilder.create().texOffs(8,24).addBox(-1.0F,0.0F,-1.0F,2.0F,5.0F,2.0F,false), PartPose.offsetAndRotation(1.5F,0.0F,0.0F,0,0,0));PartDefinition head=body.addOrReplaceChild("head", CubeListBuilder.create().texOffs(0,0).addBox(-2.5F,-5.0F,-2.5F,5.0F,5.0F,5.0F,false), PartPose.offsetAndRotation(0.0F,-5.0F,0.0F,0,0,0));PartDefinition chest2=chest1.addOrReplaceChild("chest2", CubeListBuilder.create().texOffs(0,18).addBox(-2.0F,-2.0F,0.0F,4.0F,2.0F,4.0F,false), PartPose.offsetAndRotation(0.0F,-3.0F,0.0F,1.0555751F,0.0F,0.0F));PartDefinition monster=chest1.addOrReplaceChild("monster", CubeListBuilder.create().texOffs(15,0).addBox(-1.0F,-2.0F,0.0F,2.0F,2.0F,2.0F,false), PartPose.offsetAndRotation(0.0F,-2.0F,1.5F,0.1563815F,-0.11728612F,0.0F));monster.addOrReplaceChild("monsterLeftEye", CubeListBuilder.create().texOffs(21,0).addBox(-0.5F,-0.5F,-0.5F,1.0F,1.0F,1.0F,false), PartPose.ZERO);monster.addOrReplaceChild("monsterRightEye", CubeListBuilder.create().texOffs(21,0).addBox(-0.5F,-0.5F,-0.5F,1.0F,1.0F,1.0F,true), PartPose.ZERO);monster.addOrReplaceChild("monsterLeftEar", CubeListBuilder.create().texOffs(24,0).addBox(-1.0F,-1.0F,0.0F,1.0F,1.0F,0.0F,false), PartPose.ZERO);monster.addOrReplaceChild("monsterRightEar", CubeListBuilder.create().texOffs(24,0).addBox(0.0F,-1.0F,0.0F,1.0F,1.0F,0.0F,false), PartPose.ZERO);head.addOrReplaceChild("leftEar", CubeListBuilder.create().texOffs(0,0).addBox(-1.0F,-3.0F,0.0F,2.0F,3.0F,0.0F,false), PartPose.offsetAndRotation(2.0F,-4.5F,0.0F,0.0F,0.0F,0.5235988F));head.addOrReplaceChild("rightEar", CubeListBuilder.create().texOffs(0,0).addBox(-1.0F,-3.0F,0.0F,2.0F,3.0F,0.0F,true), PartPose.offsetAndRotation(-2.0F,-4.5F,0.0F,0.0F,0.0F,-0.5235988F));head.addOrReplaceChild("nose", CubeListBuilder.create().texOffs(18,8).addBox(-1.0F,0.0F,-2.0F,2.0F,2.0F,2.0F,false), PartPose.offsetAndRotation(0.0F,-3.0F,-2.5F,0,0,0));return LayerDefinition.create(mesh,32,32);} 
    @Override public void setupAnim(GreedyFamiliarRenderState s){super.setupAnim(s);head.zRot=0;rightArm.zRot=0;leftArm.zRot=0;}
}
